import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final BigInteger MODULUS = new BigInteger("998244353");
    static void printError() {
        System.out.println(-1);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String line = br.readLine();
        int t = 1;
        // t = Integer.parseInt(line);
        while (t-- > 0) {
            line = br.readLine();
            StringTokenizer st = new StringTokenizer(line);
            long n = Long.parseLong(st.nextToken());
            long m = Long.parseLong(st.nextToken());
            line = br.readLine();
            st = new StringTokenizer(line);
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            long length = r - l;
            long evenCount = length / 2 + 1;
            long oddCount = (length + 1) / 2;
            if ((n * m) % 2 == 1) {
                BigInteger base = BigInteger.valueOf(length + 1);
                BigInteger answer = base.modPow(BigInteger.valueOf(n * m), MODULUS);
                pw.println(answer);
            } else {
                BigInteger pow1 = BigInteger.valueOf(evenCount + oddCount).modPow(BigInteger.valueOf(n * m), MODULUS);
                BigInteger pow2 = BigInteger.valueOf(evenCount - oddCount).modPow(BigInteger.valueOf(n * m), MODULUS);
                BigInteger sum = pow1.add(pow2);
                BigInteger invTwo = BigInteger.valueOf(2).modInverse(MODULUS);
                BigInteger result = sum.multiply(invTwo).mod(MODULUS);
                pw.println(result);
            }
        }
        pw.flush();
    }
}
